waves.point_eqs_str:
t_abs = sample*3;
t_rel = sample-time/5;

ampl = 2*t_abs/2 ;

k1=sin(time/13);
k2=sin(time/12);
ox = ampl*sin (t_abs*(31+5*k1)) + sin(time/25)*(1-t_abs)*0.4  ;
oy = ampl*cos (t_abs*(31+5*k2));
oz = -1  ;


r = sqr(sin(t_rel*3.4));
g = sqr(sin(t_rel));
b = sqr (cos(t_rel*1.8));

a=0.1*(sin(t_abs*3)) 
  + 0.6*q3*below (abs(1-t_abs-t1 ),0.3);

xang = time/9.5;
yang = 0*time/7;
zang = -time/22;
fov = 0.5;


// Rotation um x,y,z

mx = ox*cos(zang) - oy*sin(zang);
my = ox*sin(zang) + oy*cos(zang);

ox = mx;
oy = my;
mx = ox*cos(yang) + oz*sin(yang);
mz = - ox*sin(yang) + oz*cos(yang);
ox = mx;
oz = mz;
my = oy*cos(xang) - oz*sin(xang);
mz = oy*sin(xang) + oz*cos(xang);
oy = my;
oz = mz;

oz = oz - 6;
x = ox*fov/oz +0.5;
//x = (x-.5)*0.75 + 0.5;
y = oy*fov/oz + 0.5;

