tm = time*.1;
t1 = t1*sin(tm*t4) + (1-t1)*sin(tm*t7);
t2 = t2*sin(tm*t5) + (1-t2)*sin(tm*t8);
t3 = t3*sin(tm*t6) + (1-t3)*sin(tm*1);

tic = min(time - tin,1);
tin = time;

tva = (tic*q1*.5);
tvb = (tic*q2*.5);
tvc = (tic*q3*.5);

q1 = tva;
q2 = tvb;
q3 = tvc;

sz = .5;
len = q4;
t4 = len;

waves.point_eqs_str:
ang = 0;
len = t4;
mad = .6;

it = if(above(sample,0),(it+equal(lev,7)),1);
ita = (ita + 1)*above(sample,0);

mod = if(equal(it%2,0),1,  if(equal((it+1)%4,0),2,  if(equal((it+3)%8,0),3,  if(equal((it+7)%16,0),4,  if(equal((it+15)%32,0),5,  if(equal((it+31)%64,0),6,  if(equal((it+63)%128,0),7,7)  ))))));

sw = sw - 1;
sw = if(equal(lev,7),mod,sw)*above(sample,0);

lev = if(above(sample,0),if(above(sw,0),lev-1,lev+1),7);
a = lev*.1*1.46;

ar = if(above(sample,0),ar,1);
ar = if(equal(lev,0),ar*-1,ar);
br = if(above(sample,0),br,1);
br = if(equal(lev,1),br*-1,br);
cr = if(above(sample,0),cr,1);
cr = if(equal(lev,2),cr*-1,cr);
dr = if(above(sample,0),dr,1);
dr = if(equal(lev,3),dr*-1,dr);
er = if(above(sample,0),er,1);
er = if(equal(lev,4),er*-1,er);
fr = if(above(sample,0),fr,1);
fr = if(equal(lev,5),fr*-1,fr);
gr = if(above(sample,0),gr,1);
gr = if(equal(lev,6),gr*-1,gr);

mlev = lev*above(sample,0);

swi = equal(q4,0)*equal(sample,0);

ha = if(swi,1-2*int(rand(2)),ha);
hb = if(swi,1-2*int(rand(2)),hb);
hc = if(swi,1-2*int(rand(2)),hc);
hd = if(swi,1-2*int(rand(2)),hd);
he = if(swi,1-2*int(rand(2)),he);
hf = if(swi,1-2*int(rand(2)),hf);
hg = if(swi,1-2*int(rand(2)),hg);

aang = if(above(sample,0),aang,aang + (q1*.8 + q2*.1 + q3*.1)*ha*1);
bang = if(above(sample,0),bang,bang + (q1*.57 + q2*.33 + q3*.1)*hb*1.33);
cang = if(above(sample,0),cang,cang + (q1*.33 + q2*.57 + q3*.1)*hc*1.67);
dang = if(above(sample,0),dang,dang + (q1*.1 + q2*.8 + q3*.1)*hd*2);
eang = if(above(sample,0),eang,eang + (q1*.1 + q2*.57 + q3*.33)*he*2.33);
fang = if(above(sample,0),fang,fang + (q1*.1 + q2*.33 + q3*.57)*hf*2.67);
gang = if(above(sample,0),gang,gang + (q1*.1 + q2*.1 + q3*.8)*hg*3);

aang = 1.57;
bang = 1.57;
cang = 1.57;
dang = 1.57;
eang = 1.57;
fang = 1.57;
gang = 1.57;

oz = 0;

len = len*mad;
ox = above(lev,0)*sin(aang)*len*ar;
oy = above(lev,0)*cos(aang)*len;

an = (ar*aang + br*bang)*br;
len = len*mad;
oy = oy + above(lev,1)*sin(an)*len*br;
oz = oz + above(lev,1)*cos(an)*len;

an = (ar*aang + br*bang + cr*cang)*cr;
len = len*mad;
ox = ox + above(lev,2)*sin(an)*len*cr;
oz = oz + above(lev,2)*cos(an)*len;

an = (ar*aang + br*bang + cr*cang + dr*dang)*dr;
