stahlregen & fishbrain + flexi + geiss +.warp:
shader_body
{
    // PAINTERLY EFFECT:
    float2 uv2 = uv;
    const float mipbias = 0;
    float2 delta2 = texsize.zw*float2(1,1);
    float3 blurry_color = tex2D( sampler_main, uv2 + delta2 ).xyz;
    uv2.xy += (blurry_color.xy-0.37) * 0.03;

    // sample previous frame
    ret = tex2D( sampler_main, uv2 ).xyz;

    // darken over time
    ret -= 0.004;
}

stahlregen & fishbrain + flexi + geiss +.comp:
shader_body
{
    float2 uv2, uv3;
    float ang2, c, s;

    uv -= 0.5;
    uv *= aspect.xy;    

    ang2 = 6.28*0.333;
    c = cos(ang2);
    s = sin(ang2);
    uv2.x =  uv.x*c - uv.y*s;
    uv2.y =  uv.x*s + uv.y*c;

    ang2 = 6.28*0.667;
    c = cos(ang2);
    s = sin(ang2);
    uv3.x =  uv.x*c - uv.y*s;
    uv3.y =  uv.x*s + uv.y*c;

    ret = tex2D(sampler_main, uv + 0.5).xyz;
    ret = max(ret, tex2D(sampler_main,uv2 + 0.5).xyz);
    ret = max(ret, tex2D(sampler_main,uv3 + 0.5).xyz);

ret *= 1.3;
}

Stahlregen & Geiss + Zylot - Wall of Gla.warp:
#define MyGet GetPixel //GetBlur1
shader_body
{
    // GROW EFFECT - bright pixels spread radially outward.
    // BE CAREFUL - this can really thrash the texture cache! (SLOW)
    float grad_rad = 4;  //TWEAK - should be a least 4 for max. compatibility!
    float str = 2.8;      //TWEAK
    float3 d = float3(texsize.zw, 0) * grad_rad;
    float4 lums = 0;
    lums.x = lum( MyGet(uv + texsize.zw*d.xz) );
    lums.y = lum( MyGet(uv - texsize.zw*d.xz) );
    lums.z = lum( MyGet(uv + texsize.zw*d.zy) );
    lums.w = lum( MyGet(uv - texsize.zw*d.zy) );
    float2 grad = float2(lums.x-lums.y, lums.z-lums.w)*str*1000/grad_rad;
    grad = (saturate(grad*0.5+0.5)*2-1)*1.4;
    // sample previous frame
    ret = tex2D( sampler_fc_main, uv + grad*texsize.zw ).xyz;

    // darken (decay) over time
    ret *= 0.95; //or try: ret -= 0.004;
}

