float3 lavcol (float t) { return pow(.5,2*t*slow_roam_cos);}

float aTan2(float y, float x) {float angle;	 float abs_y = abs(y);
if (x >= 0) {float r = (x - abs_y) / (x + abs_y); angle = 1-r;} 
else {float r = (x + abs_y) / (abs_y - x); angle = 3-r; }	
angle = angle * .25;
return y < 0 ? -angle : angle;}

float3 project  (float dist) {float z; 
  z = dist/mul(ts,screen); z = clamp(z,-hlim,hlim);
  return float3((mul(float2x3(t,s),cross(ts,screen))*z+movxz),-z);}

float noise4 (float2 uvi) { float n1,n2,zv; zv = 0.008*time;
  n1 = lum(tex2D(sampler_noise_hq, (uvi)));
  n2 = lum(tex2D(sampler_noise_hq, (uvi*2+zv)));
  return n1 + n2/2 ;}

shader_body {
uv1 = (uv-.5)*aspect.xy+.5;
screen = float3 ((uv-float2(.5,.5+.0*pow((uv.x-.5),2)))*aspect.xy,.6);

//CLOUDS
uv2 = mul(uv1*float2(1,1),float2x2(q1,q2,-q2,q1));
float anz = 3.0; float t_rel = q7;
cloud = 0;
for (int n=1;n<=anz;n++) {
    z = 1-frac(1.0*n/anz-1.0*frac(-t_rel/anz)); 
    inten =  (1-z)*z*2;
    uv2 = z*uv2*.2 + float2(q6,q5); //?
    tmp = sat(lum(tex2D (sampler_noise_hq,uv2 +.01*noise4(uv2*4))-.6));
    cloud = cloud + tmp*inten;}
ncloud = 1-cloud;
fcol = tex2D(sampler_test,(uv2)*.2)*1.6;
cloud *= (.2+col);

//SKY AND GROUND
rs = project (q10); float3 rs0 = rs;
float3 noise = tex2D (sampler_noise_hq,rs.xy*.1);
gnd = .3*(noise.z-.5)/rs.z;

forest = 0;
for (int m = 1; m <= 1; m++)
{ rs = project(q10+gnd);
  rs.xy += .015*(tex2D (sampler_noise_hq,float2(rs.xy/2+time*.01))-.5);; //wind
  rs1 = rs;
  rs1.xy = 0.5 + (1.0 - abs( frac( rs.xy * 0.5 ) * 2 - 1.0 )-.5); // Eo.S. mirror code 
  back = tex2D (sampler_test,rs1.xy);;
  lprof =  back.g;
  tmp =  1-(saturate(1.8*lprof-.3*(2-m))); 
  forest += back * saturate(lprof*1)*.15 ;
  gnd += tmp/pow(rs.z,2)*.3; 
}
forest *= 1-noise.x+lprof;
forest += (.2/length(abs(noise.xy-.2-forest.g/2)))/rs.z * (.5+slow_roam_sin)/4 ;
back = forest/pow(rs.z,1) * (rs.z>0) * (rs.z < hlim);

float k1 = saturate(1-10/abs(pow(rs.z,1.8)));
back = lerp(back,.12*lavcol(k1), k1) ;;

ret1 = lerp(tex2D(sampler_main,uv),2*GetBlur1(uv),.0) *3 * ncloud;
ret2 = (GetBlur2(uv) + GetBlur3(uv))*2.0;
ret1 = lerp (ret1, ret2, 2*cloud);;
ret = back*ncloud + ret1 + cloud/3;


uv2 = uv1-float2(q11,q12);
float flash = q13/(length(uv2));
flash *= flash/(abs(frac(q12*32+int(1+treb_att)*aTan2(uv2.x,uv2.y))-.5)+.14);

uv2 = uv1-float2(q14,q15);
float tt = q8+time*12;
float2 uv3 = mul (uv2,float2x2(cos(tt),-sin(tt),sin(tt), cos(tt)));

float head = .0005/abs(length(abs(uv3.x)+abs(uv3.y)))*q16;
//head = .002/(length(uv3*float2(q3,q4))-0.00*q16)*q16;

ret += pow(head+flash,ncloud)*col;

ret += GetBlur3((uv-.5)/2+.5)/pow(rs.z,2)*(rs.z>0)*lprof*2;


float2 uv5  = (normalize(uv2)-float2(cos(q8),sin(q8)))*q16/6;
float ray1 = saturate( (1-8*q9*length(uv5))) *0.1/length(uv2);
ray1 = saturate(exp (-8*q9*length(uv5)) );
ret += ray1*(0.25+2*cloud) ;


}

