Goody - Lights in the Sky.warp:
shader_body
{
    // sample previous frame
    ret = tex2D( sampler_fc_main, uv);

    //Layer code - Thanks to flexi.    
    float2 uv1 = lerp(uv_orig,uv,1); //equals uv
    float2 uv2 = lerp(uv_orig,uv,0.2); // 20% of uv
    float2 uv3 = lerp(uv_orig,uv,0.4); //20% of uv but in the opposite direction

    ret.x = GetPixel(uv1).x*0.97;
    ret.y = GetPixel(uv2).y*0.98;
    ret.z = GetPixel(uv3).z*0.96+ret.xy*.25;

    // darken (decay) over time
    ret -= .0085+.005*ret ; 
}

Goody - Lights in the Sky.comp:
shader_body
{
    ret = tex2D(sampler_main,uv);    

    float3 bl = GetBlur3(uv).xyz;
    float3 base = GetPixel(uv).xyz;

    float3 blum = ret+lum(base+bl)+GetPixel(uv.xy); 

    ret += bl+lerp(ret.x,bl.x*float3(0.24,0.9,0.138),base.y); 
    ret += bl+lerp(ret.y,bl.y*float3(0.9,0.25,0.1),base.x); 
    ret += bl+lerp(ret.z,bl.z*float3(0.31,0.12,0.18),base.z);

    ret += bl*(frac(base)+frac(bl))+blum; 
    ret += frac(ret+bl);

    ret*=ret;
}

