#define sat saturate
sampler sampler_clouds;
float z, sun, tmp;
float2 uv1, uv2, dz;
float3 sky, cloud, lea;
static float2 hor = float2 (texsize.z,0)*1;
static float2 ver = float2 (0,texsize.w)*1;

float2 noise4 (float2 uvi) { float2 n1,n2,n3,n4,n5, zv; zv = 0.003*time;
  n1 = tex2D(sampler_noise_hq, (uvi));
  n2 = tex2D(sampler_noise_hq, (uvi*3+zv));
  n3 = tex2D(sampler_noise_hq, (uvi*9+zv));
  return sat(n1 + n2/3 + n3/9-0.5);}

shader_body {
uv1 = uv-.5;
tmp = 0; 
for (int n = 1; n <= 4; n++) {
  uv2 = 0.16*uv1 * (1-tmp*.05)*(.5+uv.y)*q10 + .004*time;
  tmp = noise4(uv2).x;
}
cloud = sat(tmp) ;

ret = float3 (0.2,0.4,1.25)*sat(uv.y)*(rand_preset.z-0.2)+cloud*0.5*(1.4-uv.y);
ret += 0.1/length(uv-1.1*rand_preset.xy+0*noise4(uv*0.25)*.25) * float3 (1,0.8,0.5)* sat(1-cloud);
ret *= 1-pow(rad,2)*0.7;
uv2 = (uv-0.5)*0.5+0.45+0.05*q3;
dz.x=GetPixel(uv2-hor)-GetPixel(uv2+hor);
dz.y=GetPixel(uv2-ver)-GetPixel(uv2+ver);

lea = GetPixel(uv2);
ret *= sat (1-lea.b);
ret += lea*float3(1,1,0) * (1+q12);

lea =  lerp(2*GetBlur1(uv),GetPixel(uv),sat(6*q10-2)) * sat(1-8*lea.b) ;
ret *= sat (1-lea.b*0.8);
ret += lea*float3(1,1,0) * (1-q12);

ret = lerp (lum(ret)*(q20*0.6+0.4),ret,q20);
//if (ret.r == 0) {discard;}

}
